# FILE: Chart.yaml
apiVersion: v2
name: nginx-reverse-proxy
description: NGINX reverse proxy with custom nginx.conf, LoadBalancer Service, and NetworkPolicy restricting upstream egress
type: application
version: 0.1.0
appVersion: "1.27.2"
---
# FILE: values.yaml
replicaCount: 2

image:
  repository: nginx
  tag: "1.27.2-alpine"
  pullPolicy: IfNotPresent

imagePullSecrets: []
nameOverride: ""
fullnameOverride: ""

serviceAccount:
  create: true
  annotations: {}
  name: ""

podAnnotations: {}
podLabels: {}

podSecurityContext:
  fsGroup: 101

securityContext:
  allowPrivilegeEscalation: false
  runAsNonRoot: true
  runAsUser: 101
  runAsGroup: 101
  readOnlyRootFilesystem: true
  capabilities:
    drop:
      - ALL

service:
  type: LoadBalancer
  port: 80
  annotations: {}
  externalTrafficPolicy: Cluster
  loadBalancerSourceRanges: []

resources:
  limits:
    cpu: 200m
    memory: 256Mi
  requests:
    cpu: 100m
    memory: 128Mi

nodeSelector: {}
tolerations: []
affinity: {}

topologySpreadConstraints: []
priorityClassName: ""

terminationGracePeriodSeconds: 60

dns:
  resolver: "kube-dns.kube-system.svc.cluster.local"

upstream:
  host: "example.org"
  port: 80

networkPolicy:
  enabled: true
  ingress:
    # If empty, ingress will be allowed from anywhere (0.0.0.0/0 and ::/0) to the service port
    allowedCIDRs: []
  egress:
    # Allows DNS queries to kube-dns/coredns in kube-system namespace
    allowDNS: true
    # List of CIDRs to allow egress to (e.g., ["10.0.0.0/8","192.168.0.0/16"])
    allowedIPBlocks: []
    # Allow egress to pods in namespaces matching these labels (example: {"kubernetes.io/metadata.name": "default"})
    toNamespaceSelector: {}
    # Allow egress to pods in the same namespace matching these labels (example: {"app": "backend"})
    toPodSelector: {}

pdb:
  enabled: true
  minAvailable: 1
---
# FILE: templates/_helpers.tpl
{{- define "nginx-reverse-proxy.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" -}}
{{- end -}}

{{- define "nginx-reverse-proxy.fullname" -}}
{{- if .Values.fullnameOverride -}}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" -}}
{{- else -}}
{{- $name := default .Chart.Name .Values.nameOverride -}}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" -}}
{{- end -}}
{{- end -}}

{{- define "nginx-reverse-proxy.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" -}}
{{- end -}}

{{- define "nginx-reverse-proxy.labels" -}}
app.kubernetes.io/name: {{ include "nginx-reverse-proxy.name" . }}
helm.sh/chart: {{ include "nginx-reverse-proxy.chart" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- end -}}

{{- define "nginx-reverse-proxy.selectorLabels" -}}
app.kubernetes.io/name: {{ include "nginx-reverse-proxy.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end -}}

{{- define "nginx-reverse-proxy.serviceAccountName" -}}
{{- if .Values.serviceAccount.create -}}
{{- default (include "nginx-reverse-proxy.fullname" .) .Values.serviceAccount.name -}}
{{- else -}}
{{- default "default" .Values.serviceAccount.name -}}
{{- end -}}
{{- end -}}

{{- define "nginx-reverse-proxy.nginxConf" -}}
worker_processes 1;

events {
  worker_connections 1024;
}

http {
  log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                  '$status $body_bytes_sent "$http_referer" '
                  '"$http_user_agent" "$http_x_forwarded_for"';
  access_log /var/log/nginx/access.log main;
  error_log /var/log/nginx/error.log warn;

  sendfile on;
  tcp_nopush on;
  tcp_nodelay on;
  keepalive_timeout 65;

  # Use cluster DNS for upstream name resolution
  resolver {{ .Values.dns.resolver }} valid=5s ipv6=off;

  upstream backend {
    server {{ .Values.upstream.host }}:{{ .Values.upstream.port }};
    keepalive 64;
  }

  server {
    listen 8080;
    server_tokens off;

    location /healthz {
      access_log off;
      return 200 'ok';
    }

    location / {
      proxy_pass http://backend;
      proxy_http_version 1.1;

      proxy_set_header Host $host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
      proxy_set_header Connection "";

      proxy_buffering on;
      proxy_buffers 16 16k;
      proxy_busy_buffers_size 64k;

      proxy_read_timeout 60s;
    }
  }
}
{{- end -}}
